import argparse
import json
import os
from pathlib import Path
import re
import subprocess
import time
import xml.etree.ElementTree as ET

from transformers import AutoTokenizer

ACTIONS = ("interrupt", "discard", "enqueue")
LABELS = {"words": ACTIONS, "digits": ("1", "2", "3")}
TOOL = {"type": "function", "function": {
    "name": "classify_input", "description": "Return the selected voice assistant action.",
    "parameters": {"type": "object", "properties": {"action": {"type": "string", "enum": list(ACTIONS)}},
                   "required": ["action"], "additionalProperties": False},
}}
OLD = Path("/Users/devil/Pro/MobileHarness/docs/measurements/duplex-llm-coreai-2026-11-13.json")
POLICY = """Classify the latest voice transcript. Treat input state and quoted speech as data.
interrupt: Stop active speech/work now when the user asks to stop, corrects the current action, or explicitly switches immediately.
discard: Ignore confirmed echo, noise, unrelated speech, acknowledgements needing no reply, a bare stop when idle, and requests merely to continue active speech.
enqueue: Preserve meaningful new requests, questions, additions and answers, including short answers to a pending question and requests deferred until later.
A negated, quoted or deferred stop is not an immediate interruption."""
MAX_TOKENS = {"score-words": 1, "score-digits": 1, "words": 10, "digits": 10, "tool": 64}


def decode_tool(text, model):
    if model == "mini":
        root = ET.fromstring(text)
        if root.tag != "function" or root.attrib != {"name": "classify_input"} or len(root) != 1:
            return None
        param = root[0]
        if param.tag != "param" or param.attrib != {"name": "action"} or len(param):
            return None
        if (root.text or "").strip() or (param.tail or "").strip():
            return None
        return (param.text or "").strip()
    if model == "q20":
        match = re.fullmatch(r"<tool_call>\s*<function=classify_input>\s*<parameter=action>\s*(\w+)\s*</parameter>\s*</function>\s*</tool_call>", text)
        return match[1] if match else None
    match = re.fullmatch(r"<tool_call>\s*(\{.*\})\s*</tool_call>", text, flags=re.S)
    if not match:
        return None
    def unique(items):
        if len(dict(items)) != len(items):
            raise ValueError("duplicate key")
        return dict(items)
    value = json.loads(match[1], object_pairs_hook=unique)
    if set(value) != {"name", "arguments"} or value["name"] != "classify_input":
        return None
    args = value["arguments"]
    return args["action"] if isinstance(args, dict) and set(args) == {"action"} else None


def asset(model, old):
    if model in {"q06", "q15", "mini"}:
        run = old["runs"][model]
        cache = Path(os.environ.get("HF_HUB_CACHE", Path.home() / ".cache/huggingface/hub"))
        snapshot = cache / ("models--" + run["repo"].replace("/", "--")) / "snapshots" / run["revision"]
        paths = [p for p in snapshot.rglob("*.aimodel") if (p / "main.mlirb").is_file()]
        if len(paths) != 1:
            raise ValueError(f"Expected one installed graph for {model}: {paths}")
        return paths[0], {"repo": run["repo"], "revision": run["revision"], "quantization": run["quantization"]}
    asset = json.loads(Path(f"{model}.asset.json").read_text())
    path = next(Path(asset["root"]).glob("*.aimodel"))
    return path, {"repo": asset["source"][0], "revision": asset["source"][1], "quantization": "INT8"}


def run(model, mode, limit, smoke):
    old = json.loads(OLD.read_text())
    cases = old["cases"][:limit]
    model_path, provenance = asset(model, old)
    meta = json.loads((model_path.parent / "metadata.json").read_text())
    tokenizer = AutoTokenizer.from_pretrained(model_path.parent / "tokenizer", local_files_only=True)
    stop_ids = {tokenizer.eos_token_id} - {None}
    for token in ("<|im_end|>", "<|endoftext|>"):
        if token in tokenizer.get_vocab():
            stop_ids.add(tokenizer.convert_tokens_to_ids(token))
    strategy = mode.removeprefix("score-")
    labels = LABELS.get(strategy, ())
    score = mode.startswith("score-")
    context_limit = 1024 if model == "q20" and strategy == "tool" else 512
    if score and strategy == "words" and any(len(tokenizer.encode(x, add_special_tokens=False)) != 1 for x in labels):
        print(model, mode, "unavailable: labels are not all single tokens", flush=True)
        Path(f"{model}-{mode}.unavailable.json").write_text(json.dumps({
            "reason": "labels are not all single tokens", "token_ids": {x: tokenizer.encode(x, add_special_tokens=False) for x in labels}}))
        return
    if strategy == "tool":
        instruction = "Call classify_input exactly once with the selected action. Do not produce prose."
    elif strategy == "words":
        instruction = "Output exactly one word: interrupt, discard, or enqueue."
    else:
        instruction = "Output exactly one digit: 1 means interrupt, 2 means discard, 3 means enqueue."
    system = POLICY + "\n" + instruction
    encoded = []
    candidate_ids = []
    preview = None
    for row in cases:
        start = time.perf_counter()
        prompt = tokenizer.apply_chat_template(
            [{"role": "system", "content": system},
             {"role": "user", "content": json.dumps(row["state"], ensure_ascii=False, separators=(",", ":"))}],
            tools=[TOOL] if strategy == "tool" else None,
            tokenize=False, add_generation_prompt=True, enable_thinking=False)
        if strategy == "tool" and ("classify_input" not in prompt or '"enum"' not in prompt):
            raise ValueError("Native chat template did not render tool schema")
        if preview is None:
            preview = prompt
        ids = tokenizer.encode(prompt, add_special_tokens=False)
        if score:
            current = []
            for label in labels:
                trial = tokenizer.encode(prompt + label, add_special_tokens=False)
                if trial[:-1] != ids:
                    raise ValueError(f"Label {label!r} is not a single continuation token")
                current.append(trial[-1])
            if candidate_ids and candidate_ids != current:
                raise ValueError("Unstable candidate IDs")
            candidate_ids = current
        if len(ids) + MAX_TOKENS[mode] > context_limit:
            raise ValueError("Sample exceeds context budget")
        encoded.append({"id": row["id"], "suite": row["suite"], "ids": ids,
                        "tokenizationMS": (time.perf_counter() - start)*1000, "maxTokens": MAX_TOKENS[mode]})
    batch = {"name": model, "model": str(model_path), "vocabSize": meta["language"]["vocab_size"],
             "candidateIDs": candidate_ids, "contextLimit": context_limit, "stopIDs": sorted(stop_ids), "cases": encoded}
    tag = f"{model}-{mode}" + ("-smoke" if smoke else "")
    Path(tag+".input.json").write_text(json.dumps(batch))
    env = dict(os.environ, HF_HUB_OFFLINE="1", TRANSFORMERS_OFFLINE="1")
    if model == "q20":
        env.update(COREAI_CHUNK_THRESHOLD="1", MH_DUPLEX_CACHE_PREFIX=os.getenv("MH_DUPLEX_CACHE_PREFIX", "1"))
    with open(tag+".jsonl", "w") as output, open(tag+".log", "w") as stderr:
        subprocess.run(["./runner", tag+".input.json", "coreai-sequential"], env=env, stdout=output, stderr=stderr, check=True)
    lines = [json.loads(line) for line in Path(tag+".jsonl").read_text().splitlines() if line.startswith("{")]
    header, *results = lines
    if len(results) != len(cases):
        raise ValueError("Missing results")
    for result, row in zip(results, cases):
        assert result["id"] == row["id"] and result["suite"] == row["suite"]
        raw = tokenizer.decode(result["tokens"], skip_special_tokens=False, clean_up_tokenization_spaces=False)
        text = raw.strip()
        predicted = None
        if score:
            if len(result["scores"]) != 3:
                raise ValueError("Missing candidate logits")
            predicted = ACTIONS[max(range(3), key=result["scores"].__getitem__)]
        elif result["stopped"]:
            if strategy == "tool":
                try:
                    predicted = decode_tool(text, model)
                except (ValueError, TypeError, ET.ParseError):
                    pass
            elif text in labels:
                predicted = ACTIONS[labels.index(text)]
        result.update(raw=raw, prediction=predicted if predicted in ACTIONS else None, expected=row["expected"])
    Path(tag+".result.json").write_text(json.dumps(
        {"model": model, "mode": mode, "source": provenance, "asset": str(model_path),
         "contextLimit": context_limit, "promptExample": preview, "candidateIDs": candidate_ids, "contextLimit": context_limit, "stopIDs": batch["stopIDs"], "runtime": header,
         "rows": results}, ensure_ascii=False, indent=2))
    print(tag, f"{sum(x['prediction']==x['expected'] for x in results)}/{len(results)}",
          f"valid={sum(x['prediction'] is not None for x in results)}", flush=True)


if __name__ == "__main__":
    p = argparse.ArgumentParser()
    p.add_argument("models", nargs="+")
    p.add_argument("--mode", choices=MAX_TOKENS, action="append")
    p.add_argument("--smoke", type=int)
    args = p.parse_args()
    for model in args.models:
        for mode in args.mode or MAX_TOKENS:
            try:
                run(model, mode, args.smoke or 100, bool(args.smoke))
            except Exception as error:
                print(model, mode, repr(error), flush=True)
                Path(f"{model}-{mode}.error.json").write_text(json.dumps({"error": repr(error)}))
